    collabStopOverridePrompt: `\u0938\u0924\u094D\u0930 \u0925\u093E\u0902\u092C\u0935\u0932\u094D\u092F\u093E\u0928\u0947 \u0924\u0941\u092E\u091A\u0947 \u092A\u0942\u0930\u094D\u0935\u0940\u091A\u0947, \u0938\u094D\u0925\u093E\u0928\u093F\u0915\u0930\u093F\u0924\u094D\u092F\u093E \u0938\u0902\u0917\u094D\u0930\u0939\u093F\u0924 \u0930\u0947\u0916\u093E\u091A\u093F\u0924\u094D\u0930 \u0905\u0927\u093F\u0932\u093F\u0916\u093F\u0924 \u0939\u094B\u0908\u0932. \u0924\u0941\u0932\u093E \u0916\u093E\u0924\u094D\u0930\u0940 \u0906\u0939\u0947?

(\u0924\u0941\u092E\u094D\u0939\u093E\u0932\u093E \u0924\u0941\u092E\u091A\u0947 \u0938\u094D\u0925\u093E\u0928\u093F\u0915 \u0930\u0947\u0916\u093E\u091A\u093F\u0924\u094D\u0930 \u0920\u0947\u0935\u093E\u092F\u091A\u0947 \u0905\u0938\u0932\u094D\u092F\u093E\u0938, \u0924\u094D\u092F\u093E\u0910\u0935\u091C\u0940 \u092B\u0915\u094D\u0924 \u092C\u094D\u0930\u093E\u0909\u091D\u0930 \u091F\u0945\u092C \u092C\u0902\u0926 \u0915\u0930\u093E.)`,
    errorAddingToLibrary: "\u0938\u0902\u0917\u094D\u0930\u0939\u093E\u0924 \u0924\u0924\u094D\u0935 \u091C\u094B\u0921\u0942 \u0936\u0915\u0932\u094B \u0928\u093E\u0939\u0940",
    errorRemovingFromLibrary: "\u0938\u0902\u0917\u094D\u0930\u0939\u093E\u0924\u0942\u0928 \u0924\u0924\u094D\u0935 \u0915\u093E\u0922\u0942 \u0936\u0915\u0932\u094B \u0928\u093E\u0939\u0940",
